(3, 'Test Email', 'feraha@mailinator.com', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n    \n    <p style=\"font-size: 16px; color: #555;\">\n        This is a test campaign email from our system.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        If you are receiving this email, the campaign sending functionality is working correctly.\n    </p>\n\n    <div style=\"margin: 20px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #000; color: #fff; padding: 12px 20px; text-decoration: none; border-radius: 5px;\">\n            Visit Website\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Regards,<br/>\n        Testing Team\n    </p>\n</div>', 'all', NULL, NULL, 16, 0, 'sent', NULL, '2026-04-08 12:03:04.109', '2026-04-08 12:02:00.169', 1),
(4, 'Graduation Cap Spring Promo 2026', 'Your graduation cap awaits — exclusive offer inside 🎓', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        We’re excited to share our latest graduation cap collection with you.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        As graduation season is near, don’t miss our exclusive offers and custom designs made just for students.\n    </p>\n\n    <div style=\"margin: 25px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #16a34a; color: white; padding: 12px 22px; text-decoration: none; border-radius: 6px; display: inline-block;\">\n            Shop Now\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Best regards,<br/>\n        ClothConfig Team\n    </p>\n</div>', 'all', NULL, NULL, 1, 0, 'sent', NULL, '2026-04-08 13:18:12.703', '2026-04-08 12:15:41.839', 2),
(5, 'Hic provident et am', 'feraha@mailinator.com', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n    \n    <p style=\"font-size: 16px; color: #555;\">\n        This is a test campaign email from our system.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        If you are receiving this email, the campaign sending functionality is working correctly.\n    </p>\n\n    <div style=\"margin: 20px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #000; color: #fff; padding: 12px 20px; text-decoration: none; border-radius: 5px;\">\n            Visit Website\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Regards,<br/>\n        Testing Team\n    </p>\n</div>', 'school', 1, NULL, 3, 0, 'sent', NULL, '2026-04-08 13:47:16.524', '2026-04-08 13:47:03.156', 1),
(6, 'Facilis officia eum ', 'Your graduation cap is ready — special student offer inside', '<html>\n  <body style=\"font-family: Arial, sans-serif; padding: 20px; color: #333;\">\n    <div style=\"max-width: 600px; margin: auto; border: 1px solid #ddd; border-radius: 8px; padding: 20px;\">\n      <h1>Hello {{name}}</h1>\n\n      <p>\n        Your graduation cap is now ready for customization.\n      </p>\n\n      <p>\n        We are offering a limited-time student discount on all graduation accessories.\n      </p>\n\n      <div style=\"margin: 20px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #10b981; color: white; padding: 12px 20px; text-decoration: none; border-radius: 6px;\">\n          Order Now\n        </a>\n      </div>\n\n      <p>\n        Best regards,<br />\n        ClothConfig Team\n      </p>\n    </div>\n  </body>\n</html>', 'class', 1, NULL, 3, 0, 'sent', NULL, '2026-04-08 14:49:40.921', '2026-04-08 14:36:47.575', 3),
(7, 'Et magnam ipsum cons', 'Your graduation cap awaits — exclusive offer inside 🎓', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        We’re excited to share our latest graduation cap collection with you.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        As graduation season is near, don’t miss our exclusive offers and custom designs made just for students.\n    </p>\n\n    <div style=\"margin: 25px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #16a34a; color: white; padding: 12px 22px; text-decoration: none; border-radius: 6px; display: inline-block;\">\n            Shop Now\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Best regards,<br/>\n        ClothConfig Team\n    </p>\n</div>', 'all', NULL, NULL, 4, 0, 'sent', NULL, '2026-04-08 16:12:08.390', '2026-04-08 16:11:11.472', 2),
(8, 'Intro mail studieturs tøj', 'Velkommen til Student life - Studieturstøj', '<!DOCTYPE HTML PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional //EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\n<head>\n<!--[if gte mso 9]>\n<xml>\n  <o:OfficeDocumentSettings>\n    <o:AllowPNG/>\n    <o:PixelsPerInch>96</o:PixelsPerInch>\n  </o:OfficeDocumentSettings>\n</xml>\n<![endif]-->\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"x-apple-disable-message-reformatting\">\n  <!--[if !mso]><!--><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><!--<![endif]-->\n  \n  \n    <style type=\"text/css\">\n      \n      @media only screen and (min-width: 520px) {\n        .u-row {\n          width: 500px !important;\n        }\n\n        .u-row .u-col {\n          vertical-align: top;\n        }\n\n        \n            .u-row .u-col-100 {\n              width: 500px !important;\n            }\n          \n      }\n\n      @media only screen and (max-width: 520px) {\n        .u-row-container {\n          max-width: 100% !important;\n          padding-left: 0px !important;\n          padding-right: 0px !important;\n        }\n\n        .u-row {\n          width: 100% !important;\n        }\n\n        .u-row .u-col {\n          display: block !important;\n          width: 100% !important;\n          min-width: 320px !important;\n          max-width: 100% !important;\n        }\n\n        .u-row .u-col > div {\n          margin: 0 auto;\n        }\n\n}\n    \nbody{margin:0;padding:0}table,td,tr{border-collapse:collapse;vertical-align:top}p{margin:0}.ie-container table,.mso-container table{table-layout:fixed}*{line-height:inherit}a[x-apple-data-detectors=true]{color:inherit!important;text-decoration:none!important}