dius: 0px;\" valign=\"top\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"height: 100%;width: 100% !important;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <!--[if mso]><table role=\"presentation\" width=\"100%\"><tr><td><![endif]-->\n    <h1 style=\"margin: 0px; line-height: 140%; text-align: left; word-wrap: break-word; font-size: 22px; font-weight: 400;\"><span><span>Velkommen til Student Life – Studieturstøj 🎉</span></span></h1>\n  <!--[if mso]></td></tr></table><![endif]-->\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n  </div>\n  \n\n\n  \n  \n<div class=\"u-row-container\" style=\"padding: 0px;background-color: transparent\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: transparent;\" align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:500px;\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"width: 500px;padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\" valign=\"top\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"height: 100%;width: 100% !important;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n<div aria-label=\"menu\" class=\"menu\" style=\"text-align:center;\">\n<!--[if (mso)|(IE)]><table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" align=\"center\" style=\"\"><tr><![endif]-->\n\n  <!--[if (mso)|(IE)]><td style=\"padding:5px 15px\"><![endif]-->\n  \n  <span aria-label=\"Menu item - Page\" style=\"padding:5px 15px;display:inline-block;color:#444444;font-size:14px;\">\n    Page\n  </span>\n  \n  <!--[if (mso)|(IE)]></td><![endif]-->\n  \n\n<!--[if (mso)|(IE)]></tr></table><![endif]-->\n</div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n  </div>\n  \n\n\n  \n  \n<div class=\"u-row-container\" style=\"padding: 0px;background-color: transparent\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: transparent;\" align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:500px;\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"width: 500px;padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\" valign=\"top\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"height: 100%;width: 100% !important;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;border-radius: 0px;-webkit-border-radius: 0px; -moz-border-radius: 0px;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <div style=\"font-size: 14px; line-height: 1.4;  text-align: left; word-wrap: break-word;\">\n    <p><span>Velkommen til jeres klasseside hos Student Life.</span></p><p><br></p><p><span>I er nu blevet oprettet i studietursdelen, og herfra kan I begynde at designe jeres klassetøj sammen.</span></p><p><br></p><p><span>Sådan fungerer det:</span></p><p><span>1.</span><span style=\"white-space: pre-wrap;\">	</span><span>Vælg de produkter I ønsker</span></p><p><span>T-shirt</span></p><p><span>Hoodie</span></p><p><span>Zip hoodie</span></p><p><span>Crewneck</span></p><p><span>Bukser / shorts</span></p><p><br></p><p><span>2.</span><span style=\"white-space: pre-wrap;\">	</span><span>Tilpas jeres design</span></p><p><span>Vælg farver</span></p><p><span>Tilføj klassenavn, destination og årstal</span></p><p><span>Upload jeres eget logo eller vælg et fra biblioteket</span></p><p><span>Tilføj navne, flag og personlig tekst</span></p><p><span>3.</span><span style=\"white-space: pre-wrap;\">	</span><span>Godkend det endelige design Når designet er klar, kan hele klassen se det, inden der bestilles.</span></p><p><span>I4.</span><span style=\"white-space: pre-wrap;\">	</span><span>nviter resten af klassen Del jeres klasselink, så alle kan vælge størrelse og bestille.</span><br></p><p><span>Vigtigt at vide</span></p><p><br><span>Classrep kan redigere designet, indtil ordren er godkendt.</span></p><p><br><span>Hvis I uploader et logo eller et rygdesign, kan der gå et øjeblik, før det vises.</span></p><p><br><span>Alle ordrer bliver leveret samlet til jeres skole.</span></p><p><br><span>Jo tidligere I går i gang, desto mere tid er der til ændringer og rettelser.</span></p><p><span>Har I brug for hjælp?</span></p><p><br></p><p><span>Hvis I oplever problemer med login, design, størrelser eller bestilling, står vi klar til at hjælpe.</span></p><p><br></p><p><span>Kontakt os, så sørger vi for, at jeres klasse får præcis det tøj, I ønsker til jeres studietur.</span></p>\n  </div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n  <tr>\n    <td style=\"padding-right: 0px;padding-left: 0px;\" align=\"center\">\n      \n      <img align=\"center\" border=\"0\" src=\"https://assets.unlayer.com/projects/0/1776151217306-Student%20Life.jpg?w=297.6px\" alt=\"\" title=\"\" style=\"outline: none;text-decoration: none;-ms-interpolation-mode: bicubic;clear: both;display: inline-block !important;border: none;height: auto;float: none;width: 31%;max-width: 148.8px;\" width=\"148.8\"/>\n      \n    </td>\n  </tr>\n</table>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n  <tr>\n    <td style=\"padding-right: 0px;padding-left: 0px;\" align=\"center\">\n      \n      <img align=\"center\" border=\"0\" src=\"https://assets.unlayer.com/projects/0/1776151500373-DSC01222-Edit.jpg?w=384px\" alt=\"\" title=\"\" style=\"outline: none;text-decoration: none;-ms-interpolation-mode: bicubic;clear: both;display: inline-block !important;border: none;height: auto;float: none;width: 40%;max-width: 192px;\" width=\"192\"/>\n      \n    </td>\n  </tr>\n</table>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n  </div>\n  \n\n\n    <!--[if (mso)|(IE)]></td></tr></table><![endif]-->\n    </td>\n  </tr>\n  </tbody>\n  </table>\n  <!--[if mso]></div><![endif]-->\n  <!--[if IE]></div><![endif]-->\n</body>\n\n</html>\n', 'class', 10, NULL, 1, 0, 'sent', NULL, '2026-04-14 07:26:20.128', '2026-04-14 07:26:01.691', 4),
(9, 'test', 'Your graduation cap is ready — special student offer inside', '<html>\n  <body style=\"font-family: Arial, sans-serif; padding: 20px; color: #333;\">\n    <div style=\"max-width: 600px; margin: auto; border: 1px solid #ddd; border-radius: 8px; padding: 20px;\">\n      <h1>Hello {{name}}</h1>\n\n      <p>\n        Your graduation cap is now ready for customization.\n      </p>\n\n      <p>\n        We are offering a limited-time student discount on all graduation accessories.\n      </p>\n\n      <div style=\"margin: 20px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #10b981; color: white; padding: 12px 20px; text-decoration: none; border-radius: 6px;\">\n          Order Now\n        </a>\n      </div>\n\n      <p>\n        Best regards,<br />\n        ClothConfig Team\n      </p>\n    </div>\n  </body>\n</html>', 'all', NULL, NULL, 3, 0, 'sent', NULL, '2026-04-14 14:17:45.667', '2026-04-14 14:17:28.337', 3),
(10, 'tes', 'testMani', '', 'school', 1, NULL, 2, 0, 'sent', NULL, '2026-04-14 16:57:49.615', '2026-04-14 14:48:58.194', 2);
