(1, 'Damon Mcclure', 'feraha@mailinator.com', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n    \n    <p style=\"font-size: 16px; color: #555;\">\n        This is a test campaign email from our system.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        If you are receiving this email, the campaign sending functionality is working correctly.\n    </p>\n\n    <div style=\"margin: 20px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #000; color: #fff; padding: 12px 20px; text-decoration: none; border-radius: 5px;\">\n            Visit Website\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Regards,<br/>\n        Testing Team\n    </p>\n</div>', 'marketing', 0, 1, '2026-04-08 11:55:47.956', '2026-06-02 12:58:42.569', NULL, 0, NULL, 0, NULL, NULL),
(2, 'Testing Campaign Email Template', 'Your graduation cap awaits — exclusive offer inside 🎓', '<div style=\"font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px;\">\n    <h2 style=\"color: #333;\">Hello {{name}} 👋</h2>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        We’re excited to share our latest graduation cap collection with you.\n    </p>\n\n    <p style=\"font-size: 16px; color: #555;\">\n        As graduation season is near, don’t miss our exclusive offers and custom designs made just for students.\n    </p>\n\n    <div style=\"margin: 25px 0;\">\n        <a href=\"https://example.com\"\n           style=\"background: #16a34a; color: white; padding: 12px 22px; text-decoration: none; border-radius: 6px; display: inline-block;\">\n            Shop Now\n        </a>\n    </div>\n\n    <p style=\"font-size: 14px; color: #888;\">\n        Best regards,<br/>\n        ClothConfig Team\n    </p>\n</div>', 'marketing', 0, 0, '2026-04-08 12:07:55.522', '2026-04-08 12:07:55.522', NULL, 0, NULL, 0, NULL, NULL),
(3, 'Graduation Cap Promo Template', 'Your graduation cap is ready — special student offer inside', '', 'marketing', 0, 0, '2026-04-08 14:35:48.553', '2026-04-23 13:34:27.308', NULL, 0, 'null', 1, NULL, NULL),
(4, 'Intro mail ', 'Velkommen til Student life - Studieturstøj', '', 'marketing', 0, 1, '2026-04-14 07:25:13.268', '2026-04-23 13:33:57.791', NULL, 0, 'null', 1, NULL, NULL);
